package exercise

import (
	"math"
	"math/rand"
	"reflect"
	"testing"
	"time"
)

const inf = math.MaxInt

type wedge struct{ u, v, w int }

func buildDirected(n int, edges []wedge) [][]Edge {
	adj := make([][]Edge, n)
	for _, e := range edges {
		adj[e.u] = append(adj[e.u], Edge{To: e.v, Weight: e.w})
	}
	return adj
}

func TestDAGShortestDistances(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges []wedge
		src   int
		want  []int
	}{
		{
			name:  "six-vertex example",
			n:     6,
			edges: []wedge{{0, 1, 2}, {0, 4, 1}, {1, 2, 3}, {4, 2, 2}, {4, 5, 4}, {2, 3, 6}, {5, 3, 1}},
			src:   0,
			want:  []int{0, 2, 3, 6, 1, 5},
		},
		{
			name:  "negative edge reached late still improves what follows",
			n:     4,
			edges: []wedge{{0, 1, 1}, {0, 2, 5}, {2, 1, -10}, {1, 3, 1}},
			src:   0,
			want:  []int{0, -5, 5, -4},
		},
		{
			name:  "all lengths negative",
			n:     4,
			edges: []wedge{{0, 1, -1}, {1, 2, -2}, {0, 2, -1}, {2, 3, -3}},
			src:   0,
			want:  []int{0, -1, -3, -6},
		},
		{
			name:  "vertex numbers do not follow the edges",
			n:     5,
			edges: []wedge{{3, 0, 2}, {0, 4, 1}, {3, 1, 7}, {4, 1, -2}, {1, 2, 3}},
			src:   3,
			want:  []int{2, 1, 4, 0, 3},
		},
		{
			name:  "edges only go one way",
			n:     5,
			edges: []wedge{{0, 1, 4}, {1, 2, 1}, {2, 3, 1}, {3, 4, 1}},
			src:   2,
			want:  []int{inf, inf, 0, 1, 2},
		},
		{
			name:  "parallel edges keep the cheapest",
			n:     2,
			edges: []wedge{{0, 1, 9}, {0, 1, -3}, {0, 1, 5}},
			src:   0,
			want:  []int{0, -3},
		},
		{
			name:  "unreachable branch",
			n:     5,
			edges: []wedge{{0, 1, 3}, {2, 3, 1}, {2, 1, -4}, {3, 4, 1}},
			src:   0,
			want:  []int{0, 3, inf, inf, inf},
		},
		{
			name: "single vertex",
			n:    1,
			src:  0,
			want: []int{0},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := DAGShortestDistances(c.n, buildDirected(c.n, c.edges), c.src)
			if !reflect.DeepEqual(got, c.want) {
				t.Errorf("got %v, want %v", got, c.want)
			}
		})
	}
}

func TestDAGShortestDistancesHandlesLargeGraph(t *testing.T) {
	// The source has two chains hanging off it. Along each chain every edge
	// has length -2, and the source has an edge of length -p straight to the
	// chain's p-th vertex, so the best route to it always runs through the
	// chain's first vertex and costs 1 - 2p. The source lists its edges into
	// one chain from the far end inwards and into the other from the near end
	// outwards, and vertex numbers are shuffled. Settling vertices in order of
	// their tentative distance, relaxing every edge round after round, or
	// re-queueing a vertex whenever its distance drops all keep lowering the
	// same distances over and over on one chain or the other, so the work
	// grows with the square of the number of vertices. The expected solution
	// handles each vertex and each edge a constant number of times.
	const chain = 100000
	const n = 2*chain + 1
	label := rand.New(rand.NewSource(1)).Perm(n)
	src := label[0]
	at := func(c, p int) int { return label[1+c*chain+p-1] }

	edges := make([]wedge, 0, 4*chain)
	for p := chain; p >= 1; p-- {
		edges = append(edges, wedge{src, at(0, p), -p})
	}
	for p := 1; p <= chain; p++ {
		edges = append(edges, wedge{src, at(1, p), -p})
	}
	for c := 0; c < 2; c++ {
		for p := 1; p < chain; p++ {
			edges = append(edges, wedge{at(c, p), at(c, p+1), -2})
		}
	}
	adj := buildDirected(n, edges)

	const budget = 2 * time.Second
	done := make(chan []int, 1)
	go func() { done <- DAGShortestDistances(n, adj, src) }()

	var got []int
	select {
	case got = <-done:
	case <-time.After(budget):
		t.Fatalf("still running after %v on a graph of %d vertices and %d edges: every vertex and every edge should be handled a constant number of times, so the total work stays proportional to their sum", budget, n, len(edges))
	}

	if len(got) != n {
		t.Fatalf("got %d distances, want %d", len(got), n)
	}
	if got[src] != 0 {
		t.Fatalf("distance to the source: got %d, want 0", got[src])
	}
	for c := 0; c < 2; c++ {
		for p := 1; p <= chain; p++ {
			if v, want := at(c, p), 1-2*p; got[v] != want {
				t.Fatalf("distance to vertex %d: got %d, want %d", v, got[v], want)
			}
		}
	}
}

