package exercise

import "math"

type Edge struct {
	To     int
	Weight int
}

func DAGShortestDistances(n int, adj [][]Edge, src int) []int {
	visited := make([]bool, n)
	order := make([]int, 0, n)
	var visit func(u int)
	visit = func(u int) {
		visited[u] = true
		for _, e := range adj[u] {
			if !visited[e.To] {
				visit(e.To)
			}
		}
		order = append(order, u)
	}
	for u := 0; u < n; u++ {
		if !visited[u] {
			visit(u)
		}
	}

	dist := make([]int, n)
	for i := range dist {
		dist[i] = math.MaxInt
	}
	dist[src] = 0

	for i := len(order) - 1; i >= 0; i-- {
		u := order[i]
		if dist[u] == math.MaxInt {
			continue
		}
		for _, e := range adj[u] {
			if dist[u]+e.Weight < dist[e.To] {
				dist[e.To] = dist[u] + e.Weight
			}
		}
	}
	return dist
}
